# -*- coding: utf-8 -*-
"""MANAPRINT — Générateur TUAMOTU (A4 portrait, 12 cartons/feuille).

REGLE ABSOLUE : le decor plus bas EST la planche de Maeva, relevee au trait
   sur sa maquette (bannière « TUAMOTU », la carte des atolls avec ses îles
   Manihi · Takaroa · Arutua · Rangiroa · Fakarava · Makemo · Hikueru, les
   oiseaux, le cocotier, le coucher de soleil, les cinq cercles et le cadre).
   RIEN n'a ete redessine, rien ajoute, rien enleve : on se contente
   d'ECRIRE LES NUMEROS dans les cinq cercles. NE PAS « ameliorer ».

LA REGLE DU JEU : CINQ numeros, un par colonne (B.I.N.G.O classique) —
   B 1-15 · I 16-30 · N 31-45 · G 46-60 · O 61-75.  Le crieur sort 1-75.

L'ARC-EN-CIEL EST CARTON PAR CARTON : la planche n'est gravee qu'une fois
   (un seul carton), puis reposee douze fois, chaque fois dans la couleur de
   SON carton. En noir & blanc on la repose au gris #555555. Les chiffres
   gardent le gris de la maison impose par app.py.
"""
import io
import random
from reportlab.pdfgen import canvas
from reportlab.lib.pagesizes import A4
from reportlab.lib import colors
from reportlab.lib.units import mm
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont

try:
    from generators import securite as _sec
except Exception:
    try:
        import securite as _sec
    except Exception:
        _sec = None

try:
    pdfmetrics.registerFont(TTFont("DJLTUA", "/usr/share/fonts/truetype/dejavu/DejaVuSans-ExtraLight.ttf"))
    POLICE = "DJLTUA"
except Exception:
    POLICE = "Helvetica"

RAINBOW = [
    "#E53935", "#FB8C00", "#F9A825", "#43A047", "#00ACC1",
    "#1E88E5", "#3949AB", "#8E24AA", "#D81B60", "#6D4C41",
]
GRIS = colors.Color(0.42, 0.42, 0.42)
GRIS_CLAIR = colors.Color(0.80, 0.80, 0.80)

import os as _os
try:
    pdfmetrics.registerFont(TTFont("LMROMANTUA", _os.path.join(
        _os.path.dirname(_os.path.abspath(__file__)), "LatinModern.ttf")))
    _POLICE_ECO = "LMROMANTUA"
except Exception:
    try:
        pdfmetrics.registerFont(TTFont("DJLECOTUA", "/usr/share/fonts/truetype/dejavu/DejaVuSans-ExtraLight.ttf"))
        _POLICE_ECO = "DJLECOTUA"
    except Exception:
        _POLICE_ECO = "Helvetica"
_GRIS_ECO = colors.Color(0.40, 0.40, 0.40)
_GRAS_TRAIT = 0.012
_POLICE_P15 = _POLICE_ECO
_GRIS_P15 = colors.Color(0.14, 0.14, 0.14)

TRAIT_NB = "#555555"


def _style_chiffres(style):
    if str(style).lower() in ("p15", "premium"):
        return _POLICE_P15, _GRIS_P15
    return _POLICE_ECO, _GRIS_ECO


# ── GEOMETRIE DE LA FEUILLE (A4 portrait, 3 colonnes x 4 rangees) ──
PAGE_W, PAGE_H = A4
ASPECT = 304.0 / 331.0            # largeur/hauteur d'un carton (releve sur la maquette)
COLS_PAGE = 3
ROWS_PAGE = 4
CARTES_PAGE = COLS_PAGE * ROWS_PAGE
MARGE_X = 7 * mm
GUTTER_X = 3 * mm
GUTTER_Y = 3 * mm
CARD_W = (PAGE_W - 2 * MARGE_X - (COLS_PAGE - 1) * GUTTER_X) / COLS_PAGE
CARD_H = CARD_W / ASPECT
_BLOC_H = ROWS_PAGE * CARD_H + (ROWS_PAGE - 1) * GUTTER_Y
MARGE_TOP = 7.5 * mm
MARGE_BOT = PAGE_H - MARGE_TOP - _BLOC_H

# ── LES CINQ CERCLES, releves sur la maquette (fractions du carton :
#    fx depuis la gauche, fy depuis le HAUT). Ordre = B, I, N, G, O ──
CERCLES = [
    (0.158, 0.275),   # B  1-15   (haut-gauche)
    (0.140, 0.639),   # I  16-30  (milieu-gauche)
    (0.470, 0.856),   # N  31-45  (bas-centre)
    (0.845, 0.277),   # G  46-60  (haut-droit)
    (0.851, 0.653),   # O  61-75  (milieu-droit)
]
PLAGES = [(1, 15), (16, 30), (31, 45), (46, 60), (61, 75)]   # B, I, N, G, O

TAILLE_CHIFFRE = 34.0
_T_SERIE = 5.2


def _graver_planche(c):
    """Grave UNE fois la planche d'un carton (coords 0..CARD_W / 0..CARD_H).
    Remplissage nonzero : la couleur est prise au moment du doForm."""
    nom = "TUAMOTU_DECOR"
    if not getattr(c, "_tuamotu_forme_faite", False):
        c.beginForm(nom, lowerx=0, lowery=0, upperx=CARD_W, uppery=CARD_H)
        p = c.beginPath()
        for contour in _DECOR.split("|"):
            i = 0
            n = len(contour)
            while i < n:
                cmd = contour[i]
                j = i + 1
                while j < n and contour[j] not in "mlc":
                    j += 1
                v = [float(x) for x in contour[i + 1:j].split(",")]
                if cmd == "m":
                    p.moveTo(v[0] / 1000.0 * CARD_W, CARD_H - v[1] / 1000.0 * CARD_H)
                elif cmd == "l":
                    p.lineTo(v[0] / 1000.0 * CARD_W, CARD_H - v[1] / 1000.0 * CARD_H)
                else:
                    p.curveTo(v[0] / 1000.0 * CARD_W, CARD_H - v[1] / 1000.0 * CARD_H,
                              v[2] / 1000.0 * CARD_W, CARD_H - v[3] / 1000.0 * CARD_H,
                              v[4] / 1000.0 * CARD_W, CARD_H - v[5] / 1000.0 * CARD_H)
                i = j
            p.close()
        c.drawPath(p, stroke=0, fill=1)
        c.endForm()
        c._tuamotu_forme_faite = True
    return nom


def _poser_carton(c, x0, y0, couleur):
    nom = _graver_planche(c)
    c.saveState()
    c.setFillColor(couleur)
    c.translate(x0, y0)
    c.doForm(nom)
    c.restoreState()


def _gen_grille(rng):
    """CINQ numeros : un par colonne B.I.N.G.O."""
    return [rng.randint(lo, hi) for (lo, hi) in PLAGES]


def _tirer(rng, deja):
    for _ in range(400):
        grille = _gen_grille(rng)
        cle = tuple(grille)
        if cle not in deja:
            deja.add(cle)
            return grille
    return grille


def _dessiner_carton(c, x0, y0, grille, serie, couleur, style="eco"):
    police_ch, gris_ch = _style_chiffres(style)
    _poser_carton(c, x0, y0, couleur)
    taille = TAILLE_CHIFFRE
    for k, (fx, fy) in enumerate(CERCLES):
        cx = x0 + CARD_W * fx
        cy = y0 + CARD_H * (1.0 - fy) - taille * 0.36
        val = grille[k]
        if _sec:
            _sec.chiffre_micro(c, val, cx, cy, taille, gris_ch, police_ch,
                               epaisseur=_GRAS_TRAIT)
        else:
            c.setFillColor(gris_ch)
            c.setFont(police_ch, taille)
            c.drawCentredString(cx, cy, str(val))
    # numero de serie discret (suivi / anti-fraude), bas du carton
    c.setFillColor(GRIS)
    c.setFont(POLICE, _T_SERIE)
    c.drawCentredString(x0 + CARD_W / 2, y0 + 1.6 * mm, "N° %06d" % serie)
    if _sec:
        try:
            _sec.cadre_micro(c, x0, y0, CARD_W, CARD_H, serie, retrait=0.9 * mm)
        except Exception:
            pass


def generer_pdf(nb_cartes=12, serie_start=1, theme="", couleur=True,
                nom_evenement="", titre_jeu="", couleur_perso="", date_lieu="",
                telephone="", style="eco", evenement_id="", motif="",
                page_start=1, **_):
    buf = io.BytesIO()
    c = canvas.Canvas(buf, pagesize=A4, pageCompression=1)
    nb_cartes = max(1, min(int(nb_cartes), 10000))
    nb_pages = (nb_cartes + CARTES_PAGE - 1) // CARTES_PAGE
    rng = random.Random(820000 + int(serie_start))
    serie = int(serie_start)
    no_page = max(1, int(page_start))
    faits = 0
    _deja = set()
    for _p in range(nb_pages):
        if nom_evenement:
            c.setFillColor(colors.black); c.setFont(POLICE, 9)
            c.drawCentredString(PAGE_W / 2, PAGE_H - 5.4 * mm, nom_evenement)
        c.setFillColor(GRIS_CLAIR); c.setFont(POLICE, 6)
        c.drawRightString(PAGE_W - MARGE_X, PAGE_H - 5.4 * mm, "%03d" % no_page)
        for row in range(ROWS_PAGE):
            for col_i in range(COLS_PAGE):
                if faits >= nb_cartes:
                    break
                x0 = MARGE_X + col_i * (CARD_W + GUTTER_X)
                y0 = MARGE_BOT + (ROWS_PAGE - 1 - row) * (CARD_H + GUTTER_Y)
                grille = _tirer(rng, _deja)
                coul = colors.HexColor(
                    couleur_perso if (couleur and couleur_perso)
                    else RAINBOW[(serie - 1) % len(RAINBOW)] if couleur else TRAIT_NB)
                _dessiner_carton(c, x0, y0, grille, serie, coul, style=style)
                serie += 1
                faits += 1
        c.showPage()
        no_page += 1
    c.save()
    buf.seek(0)
    return buf


if __name__ == "__main__":
    with open("test_tuamotu.pdf", "wb") as f:
        f.write(generer_pdf(nb_cartes=12, couleur=True, telephone="89 22 23 05").read())
    print("TUAMOTU genere")


